/**
 * Applies parameter overrides from AI SDK options and modelParams.
 * @param modelParams - The model parameters object to modify.
 * @param options - AI SDK call options.
 * @param sapModelParams - Provider options model params.
 * @param settingsModelParams - Settings model params.
 * @param mappings - Parameter mappings for this strategy.
 * @internal
 */
export function applyParameterOverrides(
  modelParams: Record<string, unknown>,
  options: Record<string, unknown>,
  sapModelParams: Record<string, unknown> | undefined,
  settingsModelParams: Record<string, unknown> | undefined,
  mappings: readonly ParamMapping[],
): void {
  for (const mapping of mappings) {
    const value =
      (mapping.optionKey ? options[mapping.optionKey] : undefined) ??
      (mapping.camelCaseKey ? sapModelParams?.[mapping.camelCaseKey] : undefined) ??
      (mapping.camelCaseKey ? settingsModelParams?.[mapping.camelCaseKey] : undefined);

    if (value !== undefined) {
      modelParams[mapping.outputKey] = value;
    }

    if (mapping.camelCaseKey && mapping.camelCaseKey !== mapping.outputKey) {
      // eslint-disable-next-line @typescript-eslint/no-dynamic-delete
      delete modelParams[mapping.camelCaseKey];
    }
  }
}

/**
 * Returns the Anthropic prompt-caching slice of `providerMetadata[provider]` as a
 * spread-ready fragment.
 *
 * Returns `{ cacheUsage }` when at least one ephemeral TTL bucket is populated;
 * otherwise `{}` so callers can `...` it unconditionally.
 * @param tokenUsage - Raw token usage from the SAP SDK response.
 * @returns Spread-ready provider-metadata fragment.
 * @internal
 */
export function buildAnthropicCacheMetadata(tokenUsage: null | SDKTokenUsage | undefined): {
  cacheUsage?: AnthropicCacheUsage;
} {
  const details = tokenUsage?.prompt_tokens_details?.cache_creation_token_details;
  if (
    !details ||
    ((details.ephemeral_5m_input_tokens ?? 0) === 0 &&
      (details.ephemeral_1h_input_tokens ?? 0) === 0)
  ) {
    return {};
  }
  return { cacheUsage: details };
}

/**
 * Builds an EmbeddingModelV3Result from embedding data.
 * @param config - Configuration with embeddings and metadata.
 * @returns Complete embedding result for AI SDK.
 * @internal
 */
export function buildEmbeddingResult(config: EmbeddingResultConfig): EmbeddingModelV3Result {
  const {
    embeddings,
    modelId,
    providerName,
    requestId,
    responseHeaders,
    totalTokens,
    version,
    warnings,
  } = config;

  const providerMetadata: SharedV3ProviderMetadata = {
    [providerName]: {
      model: modelId,
      ...(requestId ? { requestId } : {}),
      version,
    },
  };

  return {
    embeddings,
    providerMetadata,
    ...(responseHeaders ? { response: { headers: responseHeaders } } : {}),
    usage: { tokens: totalTokens },
    warnings: warnings ? [...warnings] : [],
  };
}

/**
 * Builds a LanguageModelV3GenerateResult from SDK response.
 * @param config - Configuration with response and metadata.
 * @returns Complete generate result for AI SDK.
 * @internal
 */
export function buildGenerateResult(config: GenerateResultConfig): LanguageModelV3GenerateResult {
  const {
    modelId,
    providerName,
    requestBody,
    requestId,
    response,
    responseHeaders,
    version,
    warnings,
  } = config;

  const content = extractResponseContent(response);

  const tokenUsage = response.getTokenUsage();
  const finishReasonRaw = response.getFinishReason();
  const finishReason = mapFinishReason(finishReasonRaw);

  const textContent = response.getContent();
  const toolCalls = response.getToolCalls();

  const rawResponseBody = {
    content: textContent,
    finishReason: finishReasonRaw,
    tokenUsage,
    toolCalls,
  };

  const citations = response.getCitations?.();
  if (citations?.length) {
    for (const citation of citations) {
      content.push({
        id: String(citation.ref_id ?? citation.url),
        sourceType: "url" as const,
        title: citation.title,
        type: "source" as const,
        url: citation.url,
      });
    }
  }

  const intermediateFailures = response.getIntermediateFailures?.();

  return {
    content,
    finishReason,
    providerMetadata: {
      [providerName]: {
        ...buildAnthropicCacheMetadata(tokenUsage),
        finishReason: finishReasonRaw ?? "unknown",
        finishReasonMapped: finishReason,
        ...(intermediateFailures?.length
          ? { intermediateFailures: sanitizeAsJSONArray(intermediateFailures) }
          : {}),
        ...(requestId ? { requestId } : {}),
        version,
      },
    },
    request: {
      body: requestBody,
    },
    response: {
      body: rawResponseBody,
      headers: responseHeaders,
      id: response.responseId,
      modelId,
      timestamp: new Date(),
    },
    usage: mapTokenUsage(tokenUsage),
    warnings,
  };
}

/**
 * Builds a ModelDeployment object for the Foundation Models API SDK.
 * @param config - The strategy configuration containing deployment info and model ID.
 * @param modelVersion - Optional model version for model-based resolution.
 * @returns A ModelDeployment object for the Foundation Models API SDK.
 * @internal
 */
export function buildModelDeployment(
  config: BaseModelDeploymentConfig,
  modelVersion?: string,
): { deploymentId: string } | { modelName: string; modelVersion?: string; resourceGroup?: string } {
  const deploymentConfig = config.deploymentConfig;

  if ("deploymentId" in deploymentConfig) {
    return { deploymentId: deploymentConfig.deploymentId };
  }

  const resourceGroup =
    "resourceGroup" in deploymentConfig ? deploymentConfig.resourceGroup : undefined;

  return {
    modelName: config.modelId,
    ...(modelVersion && { modelVersion }),
    ...(resourceGroup && { resourceGroup }),
  };
}

/**
 * Builds and validates model parameters from multiple sources.
 * @param config - Configuration with options, mappings, and source parameters.
 * @returns The merged model parameters and validation warnings.
 * @internal
 */
export function buildModelParams(config: BuildModelParamsConfig): BuildModelParamsResult {
  const { options, paramMappings, providerModelParams, settingsModelParams } = config;
  const warnings: SharedV3Warning[] = [];

  const modelParams: Record<string, unknown> = deepMerge(
    settingsModelParams ?? {},
    providerModelParams ?? {},
  );

  applyParameterOverrides(
    modelParams,
    options,
    providerModelParams,
    settingsModelParams,
    paramMappings,
  );

  if (options.stopSequences && options.stopSequences.length > 0) {
    modelParams.stop = options.stopSequences;
  }

  validateModelParamsWithWarnings(
    {
      frequencyPenalty: options.frequencyPenalty,
      maxTokens: options.maxOutputTokens,
      presencePenalty: options.presencePenalty,
      temperature: options.temperature,
      topP: options.topP,
    },
    warnings,
  );

  return { modelParams, warnings };
}

/**
 * Builds SAP AI SDK-compatible tool parameters from a JSON schema.
 * @param schema - The JSON schema to convert.
 * @returns The SAP-compatible tool parameters object.
 * @internal
 */
export function buildSAPToolParameters(schema: Record<string, unknown>): SAPToolParameters {
  const schemaType = schema.type;

  if (schemaType !== undefined && schemaType !== "object") {
    return {
      properties: {},
      required: [],
      type: "object",
    };
  }

  const properties =
    schema.properties && typeof schema.properties === "object"
      ? (schema.properties as Record<string, unknown>)
      : {};

  const required =
    Array.isArray(schema.required) && schema.required.every((item) => typeof item === "string")
      ? schema.required
      : [];

  const additionalFields = Object.fromEntries(
    Object.entries(schema).filter(
      ([key]) => key !== "type" && key !== "properties" && key !== "required",
    ),
  );

  return {
    properties,
    required,
    type: "object",
    ...additionalFields,
  };
}

/**
 * Computes the non-cached prompt tokens from a prompt-token total and its cache slices.
 *
 * Returns `undefined` when the total is unknown. Returns the total unchanged when no
 * cache breakdown is reported. Otherwise subtracts both cache buckets and clamps the
 * result at zero to defend against inconsistent SDK token counts where
 * `cached + cacheWrite > prompt`.
 * @param promptTokens - Total prompt tokens reported by the SDK.
 * @param cachedTokens - Tokens served from the prompt cache.
 * @param cacheWriteTokens - Tokens written to the prompt cache.
 * @returns The non-cached prompt token count, or `undefined` when unknown.
 * @internal
 */
export function computeNoCache(
  promptTokens: number | undefined,
  cachedTokens: number | undefined,
  cacheWriteTokens: number | undefined,
): number | undefined {
  if (promptTokens == null) {
    return undefined;
  }
  if (cachedTokens == null && cacheWriteTokens == null) {
    return promptTokens;
  }
  return Math.max(0, promptTokens - (cachedTokens ?? 0) - (cacheWriteTokens ?? 0));
}

/**
 * Converts AI SDK response format to SAP-compatible format.
 * @param optionsResponseFormat - The AI SDK response format from call options.
 * @param settingsResponseFormat - The fallback response format from settings.
 * @returns The converted response format and any warning.
 * @internal
 */
export function convertResponseFormat(
  optionsResponseFormat: LanguageModelV3CallOptions["responseFormat"],
  settingsResponseFormat?: unknown,
): ConvertedResponseFormatResult {
  let responseFormat: SAPResponseFormat | undefined;
  let warning: SharedV3Warning | undefined;

  if (optionsResponseFormat?.type === "json") {
    responseFormat = optionsResponseFormat.schema
      ? {
          json_schema: {
            description: optionsResponseFormat.description,
            name: optionsResponseFormat.name ?? "response",
            schema: optionsResponseFormat.schema as Record<string, unknown>,
            strict: null,
          },
          type: "json_schema" as const,
        }
      : { type: "json_object" as const };
  } else if (settingsResponseFormat) {
    responseFormat = settingsResponseFormat as SAPResponseFormat;
  }

  if (responseFormat && responseFormat.type !== "text") {
    warning = {
      message:
        "responseFormat JSON mode is forwarded to the underlying model; support and schema adherence depend on the model/deployment.",
      type: "other",
    };
  }

  return { responseFormat, warning };
}

/**
 * Converts AI SDK tools to SAP-compatible tool format.
 * @param tools - The AI SDK tools to convert.
 * @param options - Optional per-tool parsing config.
 * @param options.parser - Reads per-tool `providerOptions['sap-ai']` and returns parsed directives, or `undefined` when none apply.
 * @param options.warnings - Sink for Zod validation issues raised while parsing.
 * @returns The converted tools and any warnings.
 * @internal
 */
export function convertToolsToSAPFormat<T extends SAPTool<unknown>>(
  tools: AISDKTool[] | undefined,
  options: ConvertToolsOptions = {},
): ConvertedToolsResult<T> {
  const { parser, warnings: parserWarnings } = options;
  const warnings: SharedV3Warning[] = [];

  if (!tools || tools.length === 0) {
    return { tools: undefined, warnings };
  }

  const convertedTools = tools
    .map((tool): null | T => {
      if (tool.type === "function") {
        const functionTool = tool as LanguageModelV3FunctionTool;
        const { parameters, warning } = extractToolParameters(functionTool);
        if (warning) {
          warnings.push(warning);
        }

        const cacheControl = parser?.(functionTool.providerOptions, parserWarnings)?.cacheControl;

        return {
          ...(cacheControl ? { cache_control: cacheControl } : {}),
          function: {
            name: tool.name,
            parameters,
            ...(tool.description ? { description: tool.description } : {}),
          },
          type: "function",
        } as T;
      } else {
        warnings.push({
          details: "Only 'function' tool type is supported.",
          feature: `tool type for ${tool.name}`,
          type: "unsupported",
        });
        return null;
      }
    })
    .filter((t): t is T => t !== null);

  return {
    tools: convertedTools.length > 0 ? convertedTools : undefined,
    warnings,
  };
}

/**
 * Creates a summary of Vercel AI SDK request options for error context.
 * @param options - The language model call options to summarize.
 * @returns An object summarizing the request for debugging.
 * @internal
 */
export function createAISDKRequestBodySummary(options: LanguageModelV3CallOptions): {
  hasImageParts: boolean;
  maxOutputTokens?: number;
  promptMessages: number;
  responseFormatType?: string;
  seed?: number;
  stopSequences?: number;
  temperature?: number;
  toolChoiceType?: string;
  tools: number;
  topK?: number;
  topP?: number;
} {
  return {
    hasImageParts: options.prompt.some(
      (message) =>
        message.role === "user" &&
        message.content.some((part) => part.type === "file" && part.mediaType.startsWith("image/")),
    ),
    maxOutputTokens: options.maxOutputTokens,
    promptMessages: options.prompt.length,
    responseFormatType: options.responseFormat?.type,
    seed: options.seed,
    stopSequences: options.stopSequences?.length,
    temperature: options.temperature,
    toolChoiceType: options.toolChoice?.type,
    tools: options.tools?.length ?? 0,
    topK: options.topK,
    topP: options.topP,
  };
}

/**
 * Resolves the SDK completion identifier from an internal `_data` payload, falling back to
 * the pipeline request id reported by `getRequestId()` when the path is not present.
 *
 * Tolerates SDKs that omit `_data` entirely or expose `getRequestId()` as a non-function.
 * @param response - SDK response object exposing `_data` and optionally `getRequestId()`.
 * @param response._data - Internal SDK payload that holds the completion id under `dataPath`.
 * @param response.getRequestId - Function returning the SAP AI Core pipeline request id.
 * @param dataPath - Dotted property path traversed under `_data` (e.g. `["final_result","id"]`).
 * @returns The first non-empty completion id found along the path, or `undefined`.
 * @internal
 */
export function extractCompletionId(
  response: { _data?: unknown; getRequestId?: () => string | undefined },
  dataPath: readonly string[],
): string | undefined {
  let cursor: unknown = response._data;
  for (const key of dataPath) {
    if (cursor !== null && typeof cursor === "object" && key in cursor) {
      cursor = (cursor as Record<string, unknown>)[key];
    } else {
      cursor = undefined;
      break;
    }
  }
  if (typeof cursor === "string" && cursor.length > 0) {
    return cursor;
  }
  const fn = response.getRequestId;
  if (typeof fn !== "function") {
    return undefined;
  }
  try {
    const rid = fn.call(response);
    return typeof rid === "string" && rid.length > 0 ? rid : undefined;
  } catch {
    return undefined;
  }
}

/**
 * Extracts content (text and tool calls) from SDK response.
 * @param response - SDK response object.
 * @returns Content array for LanguageModelV3GenerateResult.
 * @internal
 */
export function extractResponseContent(response: SDKResponse): LanguageModelV3Content[] {
  const content: LanguageModelV3Content[] = [];

  const textContent = response.getContent();
  if (textContent) {
    content.push({
      text: textContent,
      type: "text",
    });
  }

  const toolCalls = response.getToolCalls();
  if (toolCalls) {
    for (const toolCall of toolCalls) {
      content.push({
        input: toolCall.function.arguments,
        toolCallId: toolCall.id,
        toolName: toolCall.function.name,
        type: "tool-call",
      });
    }
  }

  return content;
}

/**
 * Extracts the request id and normalised headers from an SDK response.
 *
 * Resolves `requestId` from `getRequestId()` first; when absent, falls back to the
 * `x-request-id` header. Tolerates SDKs that omit `getRequestId`, expose it as a
 * non-function, or raise from the `headers` accessor. `field` selects the underlying
 * HttpResponse wrapper (`rawResponse` for foundation-models, `response` for orchestration).
 * @param response - SDK response object.
 * @param field - Property containing the underlying HttpResponse wrapper.
 * @returns Combined `{ requestId, headers }` with both fields defensively gathered.
 * @internal
 */
export function extractResponseMetadata(
  response: unknown,
  field: "rawResponse" | "response",
): ResponseMetadata {
  let requestId: string | undefined;
  const fn = (response as null | { getRequestId?: unknown })?.getRequestId;
  if (typeof fn === "function") {
    try {
      const value = (fn as () => string | undefined).call(response);
      requestId = typeof value === "string" && value.length > 0 ? value : undefined;
    } catch {
      requestId = undefined;
    }
  }

  let rawHeaders: unknown;
  try {
    const wrapper = (response as null | Record<string, unknown>)?.[field] as
      undefined | { headers?: unknown };
    rawHeaders = wrapper?.headers;
  } catch {
    rawHeaders = undefined;
  }
  const headers = rawHeaders === undefined ? undefined : normalizeHeaders(rawHeaders);

  if (requestId === undefined && typeof headers?.["x-request-id"] === "string") {
    requestId = headers["x-request-id"];
  }

  return { headers, requestId };
}

/**
 * Extracts SAP-compatible tool parameters from an AI SDK function tool.
 * @param tool - The AI SDK function tool to extract parameters from.
 * @returns The extracted parameters and optional warning.
 * @internal
 */
export function extractToolParameters(tool: LanguageModelV3FunctionTool): ExtractedToolParameters {
  const inputSchema = tool.inputSchema as Record<string, unknown> | undefined;
  const toolWithParams = tool as FunctionToolWithParameters;

  if (toolWithParams.parameters && isZodSchema(toolWithParams.parameters)) {
    try {
      const jsonSchema = z.toJSONSchema(toolWithParams.parameters);
      const schemaRecord = jsonSchema as Record<string, unknown>;
      delete schemaRecord.$schema;
      return { parameters: buildSAPToolParameters(schemaRecord) };
    } catch (error) {
      return {
        parameters: buildSAPToolParameters({}),
        warning: {
          details: `Failed to convert tool Zod schema: ${error instanceof Error ? error.message : String(error)}. Falling back to empty object schema.`,
          feature: `tool schema conversion for ${tool.name}`,
          type: "unsupported",
        },
      };
    }
  }

  if (inputSchema && hasKeys(inputSchema)) {
    const hasProperties =
      inputSchema.properties &&
      typeof inputSchema.properties === "object" &&
      hasKeys(inputSchema.properties);

    if (hasProperties) {
      return { parameters: buildSAPToolParameters(inputSchema) };
    }
  }

  return { parameters: buildSAPToolParameters({}) };
}

/**
 * Checks if an object has a callable parse method.
 * @param obj - The object to check for a parse method.
 * @returns True if the object has a callable parse method.
 * @internal
 */
export function hasCallableParse(
  obj: Record<string, unknown>,
): obj is Record<string, unknown> & { parse: (...args: unknown[]) => unknown } {
  return typeof obj.parse === "function";
}

/**
 * Checks if an object has at least one own enumerable property.
 * @param obj - The object to check.
 * @returns True if the object has one or more keys.
 * @internal
 */
export function hasKeys(obj: object): boolean {
  return Object.keys(obj).length > 0;
}

/**
 * Type guard for Zod schema objects.
 * @param obj - The object to check.
 * @returns True if the object is a Zod schema.
 * @internal
 */
export function isZodSchema(obj: unknown): obj is ZodType {
  if (obj === null || typeof obj !== "object") {
    return false;
  }
  const record = obj as Record<string, unknown>;
  return "_def" in record && "parse" in record && hasCallableParse(record);
}

/**
 * Maps provider finish reasons to Vercel AI SDK LanguageModelV3FinishReason.
 * @param reason - The raw finish reason string from the provider.
 * @returns The unified finish reason with both raw and unified representations.
 * @internal
 */
export function mapFinishReason(reason: null | string | undefined): LanguageModelV3FinishReason {
  const raw = reason ?? undefined;

  if (!reason) {
    return { raw, unified: "other" };
  }

  switch (reason.toLowerCase()) {
    case "content_filter":
    case "guardrail_intervened":
      return { raw, unified: "content-filter" };
    case "end_turn":
    case "eos":
    case "stop":
    case "stop_sequence":
      return { raw, unified: "stop" };
    case "error":
      return { raw, unified: "error" };
    case "function_call":
    case "tool_call":
    case "tool_calls":
    case "tool_use":
      return { raw, unified: "tool-calls" };
    case "length":
    case "max_tokens":
    case "max_tokens_reached":
      return { raw, unified: "length" };
    default:
      return { raw, unified: "other" };
  }
}

/**
 * Maps SAP AI SDK token usage to Vercel AI SDK LanguageModelV3Usage.
 *
 * `usage.raw` is populated only when the SDK reports fields not represented in
 * `inputTokens` / `outputTokens` (audio or prediction-token buckets); otherwise omitted.
 * @param tokenUsage - Raw token usage from the SAP SDK response.
 * @returns Mapped usage with input/output token breakdowns.
 * @internal
 */
export function mapTokenUsage(tokenUsage: null | SDKTokenUsage | undefined): LanguageModelV3Usage {
  const cachedTokens = tokenUsage?.prompt_tokens_details?.cached_tokens;
  const cacheWriteTokens = tokenUsage?.prompt_tokens_details?.cache_creation_tokens;
  const reasoningTokens = tokenUsage?.completion_tokens_details?.reasoning_tokens;
  const promptTokens = tokenUsage?.prompt_tokens;

  const promptDetails = tokenUsage?.prompt_tokens_details;
  const completionDetails = tokenUsage?.completion_tokens_details;
  const hasUnmappedFields =
    promptDetails?.audio_tokens != null ||
    completionDetails?.audio_tokens != null ||
    completionDetails?.accepted_prediction_tokens != null ||
    completionDetails?.rejected_prediction_tokens != null;

  return {
    inputTokens: {
      cacheRead: cachedTokens,
      cacheWrite: cacheWriteTokens,
      noCache: computeNoCache(promptTokens, cachedTokens, cacheWriteTokens),
      total: promptTokens,
    },
    outputTokens: {
      reasoning: reasoningTokens,
      text:
        reasoningTokens != null
          ? (tokenUsage?.completion_tokens ?? 0) - reasoningTokens
          : tokenUsage?.completion_tokens,
      total: tokenUsage?.completion_tokens,
    },
    ...(hasUnmappedFields && tokenUsage ? { raw: sanitizeAsJSONObject(tokenUsage) } : {}),
  };
}

/**
 * Maps Vercel AI SDK toolChoice to SAP Foundation Models SDK tool_choice format.
 * @param toolChoice - The Vercel AI SDK tool choice.
 * @returns The SAP SDK tool_choice format, or undefined if no mapping needed.
 * @internal
 */
export function mapToolChoice(toolChoice: AISDKToolChoice | undefined): SAPToolChoice | undefined {
  if (!toolChoice) {
    return undefined;
  }

  switch (toolChoice.type) {
    case "auto":
      return "auto";
    case "none":
      return "none";
    case "required":
      return "required";
    case "tool":
      return {
        function: { name: toolChoice.toolName },
        type: "function",
      };
    default:
      return undefined;
  }
}

/**
 * Merges provider-level `requestConfig` with the per-call `abortSignal`.
 *
 * The AI SDK `abortSignal` always wins: any `signal` present on `requestConfig` is
 * dropped so callers cannot accidentally bypass the abort contract described in the
 * JSDoc of `SAPAIProviderSettings.requestConfig`.
 * @param requestConfig - Provider-level custom request configuration.
 * @param abortSignal - Per-call abort signal from the AI SDK.
 * @returns Merged configuration, or `undefined` when there is nothing to forward.
 * @internal
 */
export function mergeRequestConfig(
  requestConfig: CustomRequestConfig | undefined,
  abortSignal: AbortSignal | undefined,
): CustomRequestConfig | undefined {
  const { signal: _dropped, ...rest } = requestConfig ?? {};
  if (abortSignal) return { ...rest, signal: abortSignal };
  return Object.keys(rest).length > 0 ? rest : undefined;
}

/**
 * Converts SAP AI SDK embedding to Vercel AI SDK format.
 * @param embedding - The embedding as number array or base64 string.
 * @returns The normalized embedding as a number array.
 * @internal
 */
export function normalizeEmbedding(embedding: number[] | string): EmbeddingModelV3Embedding {
  if (Array.isArray(embedding)) {
    return embedding;
  }
  const buffer = Buffer.from(embedding, "base64");
  const float32Array = new Float32Array(
    buffer.buffer,
    buffer.byteOffset,
    buffer.length / Float32Array.BYTES_PER_ELEMENT,
  );
  return Array.from(float32Array);
}

/**
 * Prepares embedding call by parsing provider options and validating input count.
 * @param config - Base embedding configuration.
 * @param options - Embedding model call options.
 * @returns Parsed SAP options and provider name.
 * @throws {TooManyEmbeddingValuesForCallError} When input count exceeds maximum.
 * @internal
 */
export async function prepareEmbeddingCall(
  config: BaseEmbeddingConfig,
  options: EmbeddingModelV3CallOptions,
): Promise<{ embeddingOptions: EmbeddingProviderOptions | undefined; providerName: string }> {
  const { maxEmbeddingsPerCall, modelId, provider } = config;
  const { providerOptions, values } = options;

  const providerName = getProviderName(provider);
  const sapOptions = await parseProviderOptions({
    provider: providerName,
    providerOptions,
    schema: sapAIEmbeddingProviderOptions,
  });

  if (values.length > maxEmbeddingsPerCall) {
    throw new TooManyEmbeddingValuesForCallError({
      maxEmbeddingsPerCall,
      modelId,
      provider,
      values,
    });
  }

  return { embeddingOptions: sapOptions, providerName };
}

const jsonReplacer = (_key: string, value: unknown): unknown =>
  typeof value === "bigint" ? value.toString() : value;

/**
 * Coerces an array into a JSON-conformant payload suitable for `providerMetadata` values.
 *
 * Non-serialisable entries (functions, symbols, `undefined`) are dropped or replaced
 * by `null` per `JSON.stringify` defaults. Bigint values become decimal strings.
 * Returns an empty array when the entire payload cannot be serialised (e.g. circular
 * references).
 * @param value - Candidate array.
 * @returns JSON-safe array.
 * @internal
 */
export function sanitizeAsJSONArray(value: readonly unknown[]): JSONArray {
  try {
    return JSON.parse(JSON.stringify(value, jsonReplacer)) as JSONArray;
  } catch {
    return [];
  }
}

/**
 * Coerces an object into a JSON-conformant payload suitable for `providerMetadata` or
 * `LanguageModelV3Usage.raw`.
 *
 * Non-serialisable values are dropped per `JSON.stringify` defaults. Bigint values
 * become decimal strings. Returns an empty object when the entire payload cannot be
 * serialised.
 * @param value - Candidate object.
 * @returns JSON-safe object.
 * @internal
 */
export function sanitizeAsJSONObject(value: object): JSONObject {
  try {
    return JSON.parse(JSON.stringify(value, jsonReplacer)) as JSONObject;
  } catch {
    return {};
  }
}
